def longest_decreasing_subsequence(arr):
    n = len(arr)
    dp = [[0] * n for _ in range(n)]

    for i in range(n):
        dp[i][i] = 1

    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if arr[i] > arr[j]:
                dp[i][j] = dp[i + 1][j]
            else:
                dp[i][j] = 1 + dp[i][j - 1]

    max_length = 0
    for i in range(n):
        for j in range(i):
            if dp[i][j] > max_length:
                max_length = dp[i][j]

    return max_length

